// cost: n x n matrix (row = person, col = object)
// returns assignment: person -> object
void auction(double *cost, int n, double eps, int *assign) {
    double *price = calloc(n, sizeof(double));
    int *obj_to_person = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) obj_to_person[i] = -1;
    // unassigned persons
    int *unassigned = malloc(n * sizeof(int));
    int num_un = n;
    for (int i = 0; i < n; i++) unassigned[i] = i;

    while (num_un > 0) {
        int new_num = 0;
        for (int idx = 0; idx < num_un; idx++) {
            int i = unassigned[idx];
            double best = INF, second = INF;
            int best_j = -1;
            for (int j = 0; j < n; j++) {
                double v = cost[i*n + j] + price[j];
                if (v < best) { second = best; best = v; best_j = j; }
                else if (v < second) second = v;
            }
            double bid = second - best + eps;
            price[best_j] += bid;
            int prev = obj_to_person[best_j];
            obj_to_person[best_j] = i;
            assign[i] = best_j;
            if (prev != -1) {
                assign[prev] = -1;
                unassigned[new_num++] = prev;
            }
        }
        num_un = new_num;
    }
}
```

